 18	  const API_BASE = process.env.REACT_APP_BACKEND_URL;
 19	  
 20	  const shopId = () => sessionStorage.getItem('shopId') || 'demo-shop';
 21	  
 22	  const isMockMode = () =>
 23	    !API_BASE ||
 24	    (API_BASE.startsWith('http://localhost') && !navigator.onLine);
 25	  
 26	  const getDatabaseConfig = () => {
 27	    try {
 28	      const shop = sessionStorage.getItem('shopId') || 'demo-shop';
 29	      const storageKey = `appConfig_${shop}`;
 30	      const cfg = JSON.parse(localStorage.getItem(storageKey) || '{}');
 31	      return cfg.database || {};
 32	    } catch {
 33	      return {};
 34	    }
 35	  };
 36	  
 37	  /** Build headers with the JWT we stored after Hosted-UI login */
 38	  async function authHeader() {
 39	    const token = sessionStorage.getItem('idToken');
 40	    return {
 41	      Authorization: `Bearer ${token}`,
 42	      'Content-Type': 'application/json',
 43	    };
 44	  }
 45	  
 46	  /* ────────────────────────────────────────────────────────────────
 47	     1)  CONFIG  – GET & PUT (Cognito protected)
 48	     ---------------------------------------------------------------- */
 49	  export async function fetchConfig(shop = shopId()) {
 50	    if (isMockMode()) return {};
 51	    const headers = await authHeader();
 52	    const r = await fetch(`${API_BASE}/config?shop_id=${shop}`, { headers });
 53	    if (!r.ok) throw new Error(r.statusText);
 54	    return r.json(); // {} if nothing saved yet
 55	  }
 56	  
 57	  export async function saveConfig(cfg, shop = shopId()) {
 58	    if (isMockMode()) return;
 59	    const headers = await authHeader();
 60	    
 61	    // Ensure shop_id is correctly set to the current user's shop ID
 62	    // The backend will use the shop_id from JWT claims but we set it explicitly for clarity
 63	    const payload = { ...cfg, shop_id: shop }; // partition key for DynamoDB
 64	    
 65	    const r = await fetch(`${API_BASE}/config`, {
 66	      method: 'PUT',
 67	      headers,
 68	      body: JSON.stringify(payload),
 69	    });
 70	    if (!r.ok) throw new Error(await r.text());
