import axios from 'axios';
import { handleMessage, getSuggestedOptions } from '@barber-app/booking-fsm';
import { buildContext } from './fsm-wrapper.js';

const EVO_BASE   = process.env.EVO_BASE_URL;
const EVO_KEY    = process.env.EVO_API_KEY;
const PUBLIC_URL = process.env.PUBLIC_API_URL;
const PUBLIC_KEY = process.env.PUBLIC_API_KEY;

/**
 * Evolution-API webhook handler
 * POST body is: { instanceId, data: { from, body, ... } }
 */
export const handler = async (event) => {
  try {
    const payload = JSON.parse(event.body);
    const from  = payload.data?.from;
    const text  = payload.data?.body?.text ?? '';

    // ---- fetch config/workers for this tenant -----------------
    const shopId = payload.instanceId;             // we’ll use instanceId === shop_id
    const headers = { 'x-api-key': PUBLIC_KEY };

    const [cfgRes, workersRes] = await Promise.all([
      axios.get(`${PUBLIC_URL}/public/config`,   { headers, params: { shop_id: shopId } }),
      axios.get(`${PUBLIC_URL}/public/workers`, { headers, params: { shop_id: shopId } })
    ]);

    // ---- run FSM ---------------------------------------------
    const ctx = buildContext(shopId, cfgRes.data, workersRes.data.workers);
    const { reply, context, appointment } = handleMessage(text, ctx);

    // book automatically if FSM produced one
    if (appointment) {
      await axios.post(`${PUBLIC_URL}/public/appointments/book`, appointment, { headers });
    }

    // ---- send reply back to WhatsApp -------------------------
    await axios.post(`${EVO_BASE}/message/send`, {
      instanceId : payload.instanceId,
      message    : reply,
      chatId     : from
    }, { headers: { apiKey: EVO_KEY } });

    return { statusCode: 200, body: 'ok' };
  } catch (err) {
    console.error(err);
    return { statusCode: 500, body: JSON.stringify({ error: err.message }) };
  }
};

import json
import os
import boto3
from boto3.dynamodb.conditions import Key
from decimal import Decimal
from urllib.parse import parse_qs
from datetime import datetime, timedelta

# ──────────────────────────────────────────────
# Helpers
# ──────────────────────────────────────────────
def json_safe(item: dict):
    """
    Recursively walk a dict returned by boto3 DDB client and
    convert:
      • Decimal → int/float
      • set     → list
    """
    safe = {}
    for k, v in item.items():
        if isinstance(v, Decimal):
            safe[k] = int(v) if v % 1 == 0 else float(v)
        elif isinstance(v, set):
            safe[k] = list(v)
        elif isinstance(v, dict):
            safe[k] = json_safe(v)
        else:
            safe[k] = v
    return safe

def extract_shop_id(event, default="demo-shop"):
    """Read ?shop_id=… from query-string, fallback to default."""
    qs = event.get("rawQueryString") or ""
    params = dict(pair.split("=", 1) for pair in qs.split("&") if "=" in pair)
    return params.get("shop_id", default)


class DecimalEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Decimal):
            return int(obj) if obj % 1 == 0 else float(obj)
        return super().default(obj)

SHOP_KEY = 'shop_id'          # partition key
SORT_KEY = 'sort_key'         # range key  =>  "{date}#{start_time}#{worker_id}"

def build_sort_key(date_, time_, worker_id):
    return f"{date_}#{time_}#{worker_id}"

def response(status, body):
    return {
        "statusCode": status,
        "headers": {
            "Content-Type": "application/json",
            "Access-Control-Allow-Origin": "http://localhost:3000",
            "Access-Control-Allow-Headers": "Content-Type,Authorization",
            "Access-Control-Allow-Methods": "OPTIONS,GET,POST,PUT"
        },
        "body": json.dumps(body, cls=DecimalEncoder)
    }

# ──────────────────────────────────────────────
# AWS objects
# ──────────────────────────────────────────────
APPOINTMENTS_TABLE = os.environ.get('APPOINTMENTS_TABLE', 'Appointments')
WORKERS_TABLE      = os.environ.get('WORKERS_TABLE', 'Workers')
CONFIGS_TABLE = os.environ.get('CONFIGS_TABLE', 'Configs')

dynamodb = boto3.resource('dynamodb')

configs_table = dynamodb.Table(CONFIGS_TABLE)
appointments_table = dynamodb.Table(APPOINTMENTS_TABLE)
workers_table      = dynamodb.Table(WORKERS_TABLE)

# ──────────────────────────────────────────────
# Lambda entry
# ──────────────────────────────────────────────
def lambda_handler(event, context):
    raw_path = event.get('rawPath') or event.get('path', '')
    method   = event.get('requestContext', {}).get('http', {}).get('method', '')

    # Cognito injects: event['requestContext']['authorizer']['jwt']['claims']
    # ─── Extract tenant + plan from Cognito JWT ─────────────────
    # (Api Gateway JWT Authorizer must be configured)
    claims = event['requestContext']['authorizer']['jwt']['claims']
